    written: [
      { q: "स्वैच्छिक रक्तदान का क्या अर्थ है?", a: "अपनी इच्छा से, बिना किसी दबाव या पैसे के, किसी की सहायता के लिए रक्त देना स्वैच्छिक रक्तदान है।", marks: 1 },
      { q: "रक्तदान से पहले रक्त देने वाले की जाँच कौन करता है?", a: "डॉक्टर रक्त देने वाले की जाँच करते हैं।", marks: 1 },
      { q: "रक्तदान को 'जीवनदान' क्यों कहा गया है?", a: "ज़रूरत के समय दिया गया थोड़ा-सा रक्त किसी रोगी या घायल की जान बचा सकता है। इसलिए रक्तदान को जीवनदान कहा गया है।", marks: 2 },
      { q: "रक्तदान के बारे में दो भ्रम लिखकर उनका सच बताइए।", a: "भ्रम 1: रक्तदान से कमज़ोरी आ जाती है। सच: सुरक्षित रक्तदान से कमज़ोरी नहीं आती।\nभ्रम 2: रक्तदान से बीमारी लग जाती है। सच: जाँच के बाद ही रक्त लिया जाता है, इसलिए कोई बुरा प्रभाव नहीं पड़ता।", marks: 2 },
      { q: "किन्हीं दो प्रकार के लोगों के नाम लिखिए जिन्हें रक्तदान नहीं करना चाहिए।", a: "जो किसी संक्रमित रोग से पीड़ित हों और जो किसी गंभीर बीमारी से ग्रस्त हों, उन्हें रक्तदान नहीं करना चाहिए।", marks: 2 },
      { q: "लोगों में रक्तदान एक संस्कार क्यों नहीं बन पाया? तीन कारण लिखिए।", a: "1. लोगों में जानकारी और जागरूकता की कमी है।\n2. वे कमज़ोरी और बीमारी के भ्रम से डरते हैं।\n3. अभिभावक बच्चों को इसकी प्रेरणा नहीं देते, उलटे डाँट देते हैं।", marks: 3 },
      { q: "रक्तदान के प्रति जागरूकता बढ़ाने के लिए आप स्कूल में क्या करेंगे? तीन बातें लिखिए।", a: "1. रक्तदान पर नारे और पोस्टर बनाकर लगाऊँगा।\n2. सभा में सही जानकारी देकर भ्रम दूर करूँगा।\n3. अपने माता-पिता और बड़ों को शिविर के बारे में बताकर प्रेरित करूँगा।", marks: 3 },
      { q: "एक दुर्घटना में घायल युवक को तुरंत रक्त चाहिए था। उसका रक्त-समूह B-नेगेटिव था, जो कठिनाई से मिलता है। अस्पताल ने कई लोगों से संपर्क किया और एक स्वैच्छिक दाता से रक्त मिलने पर उसकी जान बच गई।\n(i) इस युवक को रक्त मिलने में कठिनाई क्यों हुई?\n(ii) दाता का काम किस दान के समान है?\n(iii) अपना रक्त-समूह जानना क्यों ज़रूरी है?", a: "(i) नेगेटिव रक्त-समूह कम लोगों का होता है, इसलिए उसे ढूँढ़ना कठिन होता है।\n(ii) दाता का काम जीवनदान के समान है।\n(iii) रक्त-समूह पता हो तो आपातकाल में सही रक्त जल्दी मिल सकता है और हम भी ज़रूरतमंद की सहायता कर सकते हैं।", marks: 4, type: "case" }
    ]
