      { q: "'पग' का अर्थ है –", options: ["हाथ","आँख","सिर","पैर"], answer: 3, explain: "पग यानी पैर या कदम।", level: 2 },
      { q: "'निरंतर' का अर्थ है –", options: ["लगातार","कभी-कभी","बंद","कठिन"], answer: 0, explain: "निरंतर यानी बिना रुके।", level: 2 },
      { q: "'बूँद-बूँद से घड़ा भरता है' – इससे क्या सीख मिलती है?", options: ["सब काम एक दिन में होते हैं","पानी बचाना चाहिए","लगातार थोड़े-थोड़े प्रयास से बड़ा काम पूरा होता है","घड़ा बड़ा होना चाहिए"], answer: 2, explain: "कविता छोटे-छोटे लगातार प्रयासों का महत्त्व बताती है।", level: 2 },
      { q: "'अभियान' का अर्थ है –", options: ["सभा","किसी उद्देश्य के लिए चलाया गया संगठित प्रयास","खेल","यात्रा"], answer: 1, explain: "साक्षरता अभियान पढ़ना-लिखना सिखाने का संगठित प्रयास है।", level: 2 },
      { q: "'ऊँच-नीच का भेद मिटाना' का अर्थ है –", options: ["पहाड़ तोड़ना","सीढ़ी बनाना","घर बदलना","भेदभाव मिटाकर सबके साथ चलना"], answer: 3, explain: "कवयित्री सबको बराबर मानने का संदेश देती हैं।", level: 2 },
      { q: "मुन्नी की दादी पढ़ी-लिखी नहीं हैं। मुन्नी रोज़ दस मिनट उन्हें एक-एक अक्षर सिखाती है और छह महीने में दादी अपना नाम लिखने लगीं। कविता की कौन-सी बात इससे मेल खाती है?", options: ["तुरंत सब सीख लेना","उपहार देना","थोड़ा-थोड़ा रोज़ सीखना और सिखाना","प्रतियोगिता जीतना"], answer: 2, explain: "कविता कहती है कि एक-एक अक्षर सीखें और सिखाएँ।", level: 3 },
      { q: "सुमित रोज़ एक रुपया गुल्लक में डालता है और साल भर में अच्छी रकम जमा हो जाती है। यह किस भाव से मेल खाता है?", options: ["रोज़ थोड़ी बचत से धन जुड़ जाता है","घड़े में छेद हो तो पानी बह जाता है","चिड़िया दूर उड़ती है","राहगीर थक जाता है"], answer: 0, explain: "कविता में रोज़ थोड़ा पैसा बचाने से धन जुड़ने की बात है।", level: 3 },
      { q: "घड़े में छेद होने से बूँदें घड़ा खाली कर देती हैं – यह किस ओर संकेत करता है?", options: ["घड़ा सदा भरा रहता है","लापरवाही या बुरी आदत से जमा की गई मेहनत बेकार जा सकती है","बूँदें खराब होती हैं","पानी कम होता है"], answer: 1, explain: "छेद गलत आदत जैसा है जो मेहनत का फल बहा देता है।", level: 3 },
      { q: "'कृतार्थ' का अर्थ है –", options: ["निराश","क्रोधित","भयभीत","सफल और संतुष्ट"], answer: 3, explain: "कृतार्थ यानी जिसका उद्देश्य पूरा हो गया हो।", level: 3 }
