      { q: "भाई कन्हैया की सेवा की दो विशेषताएँ लिखिए।", a: "वे मित्र और शत्रु में भेद किए बिना सबको पानी पिलाते थे। वे जलती दोपहर में भी कंधे पर मशक उठाकर घायलों की सेवा करते थे।", marks: 2 },
      { q: "सिखों ने गुरु जी से भाई कन्हैया की क्या शिकायत की?", a: "उन्होंने कहा कि जिन शत्रुओं को वे बड़ी मुश्किल से घायल करते हैं, कन्हैया उन्हें पानी पिलाकर जीवन दान देता है। इसलिए शायद उसका दुश्मन से कोई नाता है।", marks: 2 },
      { q: "शिकायत पर भाई कन्हैया ने गुरु जी को क्या उत्तर दिया?", a: "उन्होंने हाथ जोड़कर कहा कि वे सबको जल पिलाते हैं, क्योंकि उन्हें हर प्राणी में गुरु जी का रूप दिखता है। उनके लिए कोई बेगाना नहीं है।", marks: 2 },
      { q: "इस कविता से हमें क्या शिक्षा मिलती है? तीन बिंदुओं में लिखिए।", a: "1. सबमें ईश्वर का रूप देखकर सबकी सेवा करनी चाहिए।\n2. सेवा में अपने-पराए का भेदभाव नहीं करना चाहिए।\n3. दुखी और घायल की सहायता करना सबसे बड़ा धर्म है।", marks: 3 },
      { q: "'सबकी सेवा' के आदर्श को हम घर और स्कूल में कैसे अपना सकते हैं? तीन उदाहरण दीजिए।", a: "1. घर में बीमार बड़ों की देखभाल करके।\n2. स्कूल में चोटिल या अकेले बच्चे की सहायता करके।\n3. बिना जाति या धर्म देखे हर ज़रूरतमंद को पानी, भोजन या दवा देकर।", marks: 3 },
      { q: "बाढ़ के समय गाँव में स्वयंसेवक अमरीक ने नाव से लोगों को निकाला और बिना किसी का परिचय पूछे सबको भोजन और दवा बाँटी।\n(i) अमरीक के किस गुण की प्रशंसा होगी?\n(ii) यह भाई कन्हैया के किस आदर्श से मेल खाता है?\n(iii) हम ऐसे समय में क्या कर सकते हैं?", a: "(i) उसकी निःस्वार्थ सेवा और दया की प्रशंसा होगी।\n(ii) यह कन्हैया के 'कोई नहीं बेगाना' के आदर्श से मेल खाता है।\n(iii) हम अपने सामर्थ्य के अनुसार भोजन, कपड़े या दवा जैसी सहायता भेज सकते हैं या स्वयंसेवकों का साथ दे सकते हैं।", marks: 4, type: "case" }
